"""Generate on-demand care/safety content; leave reference_tab unchanged."""
import json
from pathlib import Path


def main():
    mobile = Path(__file__).resolve().parents[1]
    source = mobile.parent / 'docs/update-teeth/01_DU_LIEU_2_TAB.json'
    actual = json.loads(source.read_text(encoding='utf-8'))['actual_tab']
    quote = lambda value: json.dumps(str(value), ensure_ascii=False).replace('$', r'\$')
    lines = [
        '// GENERATED by tool/generate_teething_knowledge.py; do not edit.',
        '// Source: docs/update-teeth/01_DU_LIEU_2_TAB.json (care/safety only).',
        "part of 'teething_knowledge_data.dart';", '',
        'const _careTitle = ' + quote(actual['ui_copy']['care_title_vi']) + ';',
        'const _safetyTitle = ' + quote(actual['ui_copy']['safety_title_vi']) + ';',
    ]
    ids = set()
    for key, name, expected in [('care_rules', '_careRules', 12), ('safety_rules', '_safetyRules', 8)]:
        rules = actual[key]
        if len(rules) != expected:
            raise ValueError(f'Expected {expected} {key}')
        lines.append(f'const {name} = <TeethingKnowledgeRule>[')
        for rule in rules:
            if rule['id'] in ids or not 0 <= rule['min_month'] <= rule['max_month'] <= 60:
                raise ValueError(f"Invalid rule {rule['id']}")
            ids.add(rule['id'])
            lines.extend([
                '  TeethingKnowledgeRule(',
                '    id: ' + quote(rule['id']) + ',',
                '    title: ' + quote(rule['title_vi']) + ',',
                '    text: ' + quote(rule['text_vi']) + ',',
                f"    minMonth: {rule['min_month']}, maxMonth: {rule['max_month']},",
                '    displayMode: ' + quote(rule['display_mode']) + ',',
                f"    priority: {rule['priority']},",
                *(['    knowledgeGroup: ' + quote(rule['knowledge_group']) + ',']
                  if rule.get('knowledge_group') else []),
                '  ),',
            ])
        lines.append('];')
    destination = mobile / 'lib/features/teething/teething_knowledge_rules.g.dart'
    destination.write_text('\n'.join(lines) + '\n', encoding='utf-8')
    print(f'Generated {len(ids)} on-demand care/safety entries; reference unchanged.')


if __name__ == '__main__':
    main()
